<script>
function categoryCatalog(){return {search:'',items:@json($categories->map(fn($c)=>['name'=>$c->name,'children'=>$c->children->pluck('name')->values()])->values()),norm(v){return String(v||'').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/\u200c/g,' ').replace(/\s+/g,' ').trim().toLocaleLowerCase('fa-IR')},matches(i){const q=this.norm(this.search); if(!q)return true; const c=this.items[i]; return [c.name,...c.children].some(v=>this.norm(v).includes(q))},visibleCount(){return this.items.filter((_,i)=>this.matches(i)).length}}}
</script>
